// Sort a copy of items by one or more keys, ascending, keeping the original order for ties.
export function sortBy(items, ...keys) {
  return [...items].sort((a, b) => {
    for (const k of keys) {
      if (a[k] !== b[k]) return a[k] > b[k];
    }
    return 0;
  });
}

